// 命令别名（方言支持）
export const COMMAND_ALIASES = {
  '打开工具箱': ['开启工具箱', '显示工具箱', '打开工具面板'],
  '关闭工具箱': ['关闭工具面板', '隐藏工具箱'],
  '打开设置': ['打开配置', '进入设置', '打开偏好设置'],
  '刷新页面': ['刷新', '重新加载', '刷新一下'],
  '滚到顶部': ['回到顶部', '置顶', '到顶部'],
  '滚到底部': ['到底部', '到末尾', '置底'],
  '生成图片': ['画图', '创建图片', '生成图像'],
  '生成音乐': ['作曲', '创建音乐', '生成音频']
};

// 匹配命令（支持方言）
function matchCommand(text) {
  const normalized = text.trim().toLowerCase();
  
  // 直接匹配
  if (BUILTIN_COMMANDS[text]) {
    return text;
  }
  
  // 别名匹配
  for (const [cmd, aliases] of Object.entries(COMMAND_ALIASES)) {
    for (const alias of aliases) {
      if (normalized.includes(alias.toLowerCase()) || alias.includes(text)) {
        return cmd;
      }
    }
  }
  
  // 模糊匹配（包含关键词）
  for (const cmd of Object.keys(BUILTIN_COMMANDS)) {
    if (normalized.includes(cmd.toLowerCase()) || cmd.toLowerCase().includes(normalized)) {
      return cmd;
    }
  }
  
  return null;
}

// ============ 语音识别器 ============

let recognition = null;
let isListening = false;
let commandCallback = null;

// 初始化语音识别
export function initVoiceAssistant(onCommand) {
  if (!isVoiceSupported()) {
    console.warn('[VoiceAssistant] Speech recognition not supported');
    return false;
  }
  
  const SpeechRecognition = getSpeechRecognition();
  recognition = new SpeechRecognition();
  
  recognition.lang = VOICE_CONFIG.lang;
  recognition.continuous = VOICE_CONFIG.continuous;
  recognition.interimResults = VOICE_CONFIG.interimResults;
  recognition.maxAlternatives = VOICE_CONFIG.maxAlternatives;
  
  recognition.onstart = () => {
    isListening = true;
    onVoiceStatusChange('listening');
  };
  
  recognition.onend = () => {
    isListening = false;
    onVoiceStatusChange('idle');
  };
  
  recognition.onresult = (event) => {
    const result = event.results[event.results.length - 1];
    const transcript = result[0].transcript;
    const isFinal = result.isFinal;
    
    if (isFinal && onCommand) {
      const command = matchCommand(transcript);
      if (command) {
        updateVoiceState({ totalCommands: getVoiceState().totalCommands + 1 });
        onCommand(command, transcript);
        speakFeedback(`已执行: ${command.replace('打开', '').replace('打开', '')}`);
      }
    }
  };
  
  recognition.onerror = (event) => {
    console.error('[VoiceAssistant] Error:', event.error);
    if (event.error === 'no-speech') {
      // 无语音输入，静默处理
    } else if (event.error === 'not-allowed') {
      onVoiceStatusChange('denied');
    }
  };
  
  commandCallback = onCommand;
  return true;
}

// 开始监听
export function startListening() {
  if (!recognition || isListening) return;
  
  try {
    recognition.start();
  } catch (e) {
    console.error('[VoiceAssistant] Start failed:', e);
  }
}

// 停止监听
export function stopListening() {
  if (!recognition || !isListening) return;
  
  try {
    recognition.stop();
  } catch (e) {
    console.error('[VoiceAssistant] Stop failed:', e);
  }
}

// 切换监听状态
export function toggleListening() {
  if (isListening) {
    stopListening();
  } else {
    startListening();
  }
  return isListening;
}

// 获取监听状态
export function getListeningState() {
  return isListening;
}

// 状态变化回调（需外部设置）
let statusCallback = null;

export function onVoiceStatusChange(status) {
  if (statusCallback) {
    statusCallback(status);
  }
}

export function setStatusCallback(cb) {
  statusCallback = cb;
}

// ============ 语音合成（反馈）==========

// 说话反馈
export function speakFeedback(text, options = {}) {
  const { lang = 'zh-CN', rate = 1.0, pitch = 1.0 } = options;
  
  if (!('speechSynthesis' in window)) {
    console.warn('[VoiceAssistant] Speech synthesis not supported');
    return;
  }
  
  // 取消之前的语音
  window.speechSynthesis.cancel();
  
  const utterance = new SpeechSynthesisUtterance(text);
  utterance.lang = lang;
  utterance.rate = rate;
  utterance.pitch = pitch;
  
  // 选择中文语音
  const voices = window.speechSynthesis.getVoices();
  const zhVoice = voices.find(v => v.lang.includes('zh'));
  if (zhVoice) {
    utterance.voice = zhVoice;
  }
  
  window.speechSynthesis.speak(utterance);
}

// 停止说话
export function stopSpeaking() {
  if ('speechSynthesis' in window) {
    window.speechSynthesis.cancel();
  }
}

